var LiveSimulationService = class {
  constructor(pool, tenantId, registry2, runtime, replier) {
    this.pool = pool;
    this.tenantId = tenantId;
    this.registry = registry2;
    this.runtime = runtime;
    this.replier = replier;
  }
  async run(journey, version2, n, seed = 1) {
    const { summary, cards } = await this.execute(journey, version2, n, seed);
    const quality = aggregate(cards);
    return { summary, quality, alerts: evaluateAlerts(quality) };
  }
  async compare(journey, va, vb, n, seed = 1) {
    const a = await this.execute(journey, va, n, seed);
    const b = await this.execute(journey, vb, n, seed);
    const arm = (r, v) => ({
      target: `${journey}@${v}`,
      summary: r.summary,
      quality: aggregate(r.cards)
    });
    return compareRuns(arm(a, va), arm(b, vb), a.cards, b.cards);
  }
  async execute(journey, version2, n, seed) {
    const spec = await this.registry.get(journey, version2);
    const personas = generatePersonas(spec, n, seed);
    const store = new EventStore(this.pool, this.tenantId, "sim");
    const runId = `run_${version2}_${seed}_${Date.now()}`;
    const summary = await new SimulationRunner(store, this.runtime, this.replier).run(spec, personas, { runId });
    const byId = new Map(personas.map((p) => [p.id, p]));
    const cards = [];
    for (const r of summary.results) {
      const persona = byId.get(r.personaId);
      if (!persona) continue;
      cards.push(scoreConversation(spec, await store.fold(r.leadId), persona, {
        escalated: r.outcome === "escalated",
        ghosted: r.outcome === "ghosted"
      }));
    }
    return { summary, cards };
  }
};
