// packages/web/src/server.ts
function buildServer(deps, token = null) {
  const app = (0, import_fastify.default)({ logger: false });
  const registeredRoutes = [];
  app.addHook("onRoute", (r) => {
    for (const method of [r.method].flat()) registeredRoutes.push({ method, url: r.url });
  });
  app.decorate("registeredRoutes", registeredRoutes);
  app.addHook("onRequest", async (_req, reply) => {
    reply.header("access-control-allow-origin", "*");
  });
  registerAuth(app, token);
  registerSpecRoutes(app);
  registerRoutes(app, deps);
  registerSimulateRoutes(app, deps);
  registerIntelligenceRoutes(app, deps);
  registerChatRoutes(app, deps);
  return app;
}

// server/api-handler.ts
var ready = null;
async function build() {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error("DATABASE_URL is not set");
  const pool = createPool(url, { max: 2, idleTimeoutMillis: 1e4 });
  const tenantId = process.env.TENANT_ID ?? "t1";
  const registry2 = new JourneyRegistry(pool, tenantId);
  const events = new EventStore(pool, tenantId);
  const credentialled = hasCredential();
  const runtime = credentialled ? new AgentRuntime() : new AgentRuntime(new KeywordExtractor(), offlineClient());
  const fx = {
    currency: process.env.REPORTING_CURRENCY ?? "INR",
    perUsd: Number(process.env.FX_MINOR_PER_USD ?? 8300)
  };
  const app = buildServer({
    registry: registry2,
    store: events,
    replay: new ReplayEngine(events, registry2, runtime),
    simulate: new LiveSimulationService(
      pool,
      tenantId,
      registry2,
      runtime,
      chooseReplier(credentialled)
    ),
    attribution: new AttributionEngine(events, registry2),
    insights: new InsightEngine(events, registry2),
    copilot: credentialled ? new Copilot(events, registry2) : new OfflineCopilot(events, registry2),
    chat: new ChatService(events, registry2, runtime, fx, !credentialled),
    offline: !credentialled
  }, process.env.API_TOKEN ?? null);
  await app.ready();
  return app;
}
